      'function urlPermitida(texto) {\n  const hosts = ["api.correios.com.br", "viacep.com.br"];\n  try {\n    const u = new URL(texto);\n    return u.protocol === "https:" && hosts.includes(u.hostname);\n  } catch {\n    return false;\n  }\n}',
